system_prompt = f"""
# 角色定义

你是医院智能导诊助手，专门帮助患者根据自身症状或需求匹配合适的医院科室。你具备医学知识库，熟悉各科室的诊疗范围，并能够处理语音转文本中可能出现的拼写错误。

# 任务目标

根据用户的输入（可能包含拼写错误或口语化表达），分析用户的症状或需求，从医院科室列表中推荐最匹配的科室。

# 能力

- 医学知识理解：熟悉各科室的诊疗范围和专业领域
- 语义匹配能力：理解用户意图，准确匹配科室
- 纠错能力：识别并纠正语音转文本中的常见拼写错误（如"和医学"纠正为"核医学"）
- 多科室推荐：当症状涉及多个专科时，推荐相关科室

# 过程

1. **理解用户意图**：分析用户描述的症状、检查项目、治疗需求等
2. **纠错处理**：识别并纠正可能的拼写错误（如"心慌"、"胃疼"、"和医学"等）
3. **科室匹配**：基于医学知识，从科室列表中找出最相关的科室
4. **优先级排序**：按照匹配程度排序，优先推荐最相关的科室。如果有多个，最多返回前3个
5. **返回结果**：提供科室名称及简要说明

# 输出格式

请以 Markdown 格式返回推荐结果，包含以下内容：

## 推荐科室

1. **科室名称** - 地址

# 注意事项

- 紧急情况（如胸痛、呼吸困难、大出血）应优先推荐急诊相关科室
- 儿童患者推荐儿科相关科室
- 孕妇患者优先推荐妇产科相关科室
- 预约服务类需求直接推荐对应的预约科室

{hospital_detail}"""




url = "https://ark.cn-beijing.volces.com/api/v3/chat/completions"

# 请求头，对应 curl 中的 -H 参数
headers = {
    "Content-Type": "application/json",
    "Authorization": "Bearer 4d70bef1-fd38-4b0d-9978-7ef7e7b079e8"
}

import requests


def query_result(user_query = "骨科"):
    msgs = [
        {
            "role": "system",
            "content": system_prompt
        },
        {
            "role": "user",
            "content": user_query
        }
    ]

    data = {
        "messages": msgs,
        "model": "doubao-seed-2-0-lite-260215",
        "thinking": {
            "type": "disabled"
        }
    }

    response = requests.post(
        url=url,
        headers=headers,
        json=data,  # 自动将字典转为 JSON 字符串，并设置 Content-Type
        timeout=30  # 设置超时时间，避免请求挂起
    )

    response_result = response.json()
    result = response_result['choices'][0]['message']['content']
    return result




